#!/usr/bin/env python3
"""__DISPLAY_NAME__ - SDK v3 app generated by `plexi app init`.

Plexi loads this file and calls three module-level functions by name:
``init(size, args)``, ``update(event)``, and ``view()``. Keep that shape; no
base class or registration step is needed.
"""

from __future__ import annotations

from plexi_sdk import log, state
from plexi_sdk.effects import SetState, SetTitle
from plexi_sdk.events import KeyEvent, UiAction
from plexi_sdk.ui import ActionBar, AppBar, Button, Column, FooterKeys, Spacer, Text

COUNT_KEY = "count"


def init(size, args) -> list:
    """Return startup effects.

    ``size`` is ``(width, height)`` in logical pixels. ``args`` are any extra
    arguments passed after the app path. Effects are applied after this function
    returns, then Plexi calls ``view()``.
    """
    log.info("__DISPLAY_NAME__ initialized")
    return [
        SetTitle("__DISPLAY_NAME__"),
        # Runtime state is a JSON-shaped dict. Prefer stable, small keys; view()
        # reads the snapshot with state.get(...).
        SetState({COUNT_KEY: 0}),
    ]


def update(event) -> list:
    """Handle one input/result event and return effects.

    Do not mutate Plexi state in-place. Return SetState/PersistState or other
    effect objects, and the adapter applies them after ``update`` returns.
    """
    if isinstance(event, UiAction):
        if event.handler_id == "counter-increment":
            return [SetState({COUNT_KEY: state.get(COUNT_KEY, 0) + 1})]
        if event.handler_id == "counter-decrement":
            return [SetState({COUNT_KEY: state.get(COUNT_KEY, 0) - 1})]
        if event.handler_id == "counter-reset":
            return [SetState({COUNT_KEY: 0})]

    if isinstance(event, KeyEvent) and event.pressed:
        if event.key in ("equals", "plus"):
            return [SetState({COUNT_KEY: state.get(COUNT_KEY, 0) + 1})]
        if event.key == "minus":
            return [SetState({COUNT_KEY: state.get(COUNT_KEY, 0) - 1})]
        if event.key == "r":
            return [SetState({COUNT_KEY: 0})]
    return []


def view():
    """Return the current component tree. Keep this function pure.

    Components describe UI. Effects describe host work. ``view`` should only
    read state and build components; return effects from ``update`` instead.
    """
    count = state.get(COUNT_KEY, 0)
    return Column(
        [
            AppBar("__DISPLAY_NAME__"),
            Text(str(count), size=28.0, bold=True),
            Text("Runtime state counter", size=12.0),
            Spacer(grow=True),
            ActionBar(
                [
                    Button("Increment", "counter-increment", style="primary"),
                    Button("Decrement", "counter-decrement"),
                    Button("Reset", "counter-reset", style="ghost"),
                ]
            ),
            FooterKeys(
                [
                    ("+", "increment"),
                    ("-", "decrement"),
                    ("r", "reset"),
                ]
            ),
        ],
        grow=True,
        padding=0,
    )
